) AS (
  VALUES 
    (298::BIGINT, 'No califica tan duro, y es buena gente, pero evite a toda costa matricular con él. Es súmamente desordenado, parece que llega a cada clase y decide en ese momento qué va a enseñar ese día. No se le entiende cuando explica. Divide muy mal el valor de las asignaciones.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '4e349d1f90c0715e4c26b24260d50f86e8cfa8072b4e035e21f099ef7c23218a'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Todo lo malo se reune en los cursos de Chepe. Clases super aburridas, tareas y examenes sorpresa sin instructivos claros, manda las cosas super tarde y se atrasa él mismo por eso, pone notas hasta los últimos días de entrega de actas... No califica duro pero si puede evitarlo hágalo'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores']::TEXT[], '2026-07-10T00:00:00+00:00'::TIMESTAMPTZ, '4806cbe904cd790b8ab13591822a56a86f878dc74d23f003c563bc03ab087154'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'El peor profesor que he visto nunca jamás en el TEC. No lo recomiendo para nada. Sus clases son súmamente malas, habla entre dientes y no se toma el tiempo para que sus estudiantes aprendan la materia. Tiene buenas prácticas de examen, que sugieren cómo serán sus exámenes, pero no se aprovechan'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '912c13d6aa032916f8b5ce2b7b8acdaaf7c4879f1189ef30e565ee80b42ed59d'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Evítese el tedio, en clases te vas a dormir SÍ o SÍ, y no vas a aprender nada.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-03-27T00:00:00+00:00'::TIMESTAMPTZ, 'd69bb1a6ca09013764eb1c3088cb9fc3371c37e7c257b4bb23149954e94d3d78'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'SAQUENMEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE COMO QUE 4 EXAMENEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEES DE 20% CADA UNOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOOO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'e0f5e6b942cbc8578b648d1f03933a7befdd78f5ac8e75630dfa32a453dea0f5'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'La verdad si puede evitarlo evitelo y si es de la sede de SJ preparese para no aprender nada.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2026-02-17T00:00:00+00:00'::TIMESTAMPTZ, 'a4f503293dfcaca77f266b0c96e78682161d8a341fe76367d1eda2f3da8c0ddd'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Verano Virtual Lenguajes- Es con diferencia el profe más irresponsable del TEC, entrego actas con notas FALSAS (pasando a todos) porque dejo todo para ultima hora y no habia revisado NADA, alargo tanto los examanes que tuvo que cambiar la carta del estudiante, si no le interesa aprender, meta con él'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2026-02-07T00:00:00+00:00'::TIMESTAMPTZ, '679a3b3e67d2d31e450b52b9a4121cffafd74a0fb7c4b0637c0f78c994ba920c'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Muy mala calidad en general. Las clases son muy largas y llenas de teoría sin gran cantidad de ejemplos aplicados. Hace “recesos” de 5 minutos para la clase de 3 horas. Un desorden con las fechas y calificaciones hasta el día de las actas. Exámenes son con cámara abierta y bastante específicos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, '6b4f0ccc4ef3650e0f4e17cf7c743d839de0ef9c9654f97c8e32f467bcbae395'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Entre temas dispersos y presentaciones a medias cada clase, el día del examen no se sabe ni que se va a evaluar. Las tareas y proyectos son sencillos, los quices son de asistencia,los exámenes si están un poco volados. TODO! lo revisa hasta lo último, no se saben las notas hasta la entrega de actas'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '52629aca0eb7a85971e848af13e397a2a4fd354e6a14f2f5a768d13963a7c41f'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, '(verano virtual)Todos los comentarios lo describen tal cual, irresponsable, desordenado, mediocre, incompetente, un zángano completo... nunca tiene nada preparado, pasa los exámenes de fecha un día antes porque no ha hecho el examen. Al final creo que solo puso una nota sin haber revisado nada.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-05T00:00:00+00:00'::TIMESTAMPTZ, '1d49475d019d012cffd6b7ea573c386722143519bed7a15c6550c5e247da19df'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Increíble el desorden. No calificó casi nada hasta el día de entrega de actas. Si quieres aprender sé autodidacta, de lo contrario no aprendes nada.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '764a16b70caee405e7d846bc460f503464ddade1e5d2ac6fea0a853f74577301'::TEXT, ARRAY[1162]::BIGINT[]),
    (298::BIGINT, 'Lamentable. Si piensa llevar con él, no vas a aprender nada, solo va a leer las diapositivas sacadas de universidades gringas y los trabajos se encuentran con su solución en internet. Además evalúa todo el semestre en el día de actas. Lo más probable es que pases pero sin aprender nada.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a90f65e20586403d98490e598c484240aa42c4af670ea738a6672b941d8a12b8'::TEXT, ARRAY[1162]::BIGINT[]),
    (298::BIGINT, 'Horrible profesor, no se como la "mejor u" considerada por muchos puede tener esta clase de profesores, no domina la materia, no tiene el don de la enseñanza, las evaluaciones voladisimas comparado a lo que enseña. No he aprendido nada en todo el semestre.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-10-25T00:00:00+00:00'::TIMESTAMPTZ, '7abc97ff136123cd7e067cd1ea1a7425446728182d2bd6d8fba0c6cb675a729a'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Terrible profesor. Calificó hasta el último día posible. Las evaluaciones estuvieron horribles'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7f94683b09ded84dc19453aa6f4bdc3834d1772c0a8fcc38586d6466bc528d58'::TEXT, ARRAY[1043]::BIGINT[]),
    (298::BIGINT, 'El mae calificó más del 90% del curso el mismo día de actas, desorganizado en todo el semestre. Los trabajos son bastante fáciles, son tareas y proyectos. Si quiere pasar fácil matricule con el mae, pero no va aprender nada y va a saber su nota hasta último momento.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'd26042ee33cbc6428e18b50f269c479cc1bb1c5f0b1c5cf84f79510c25ae572d'::TEXT, ARRAY[1056]::BIGINT[]),
    (298::BIGINT, 'SAQUENMEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-11T00:00:00+00:00'::TIMESTAMPTZ, 'a39fd01dac6453c72438399413bccc82dcdcfd2590dd8aa13769d8456ef6c4b0'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Bueno, otra vez me encuentro aquí describiendo lo inepto e incapaz que es José Castro. Es un "profesor" el cual no explica, las clases son verlo resolviendo ejemplos de materia que no hemos visto para la teoría básica de la materia hay que estarle preguntando que putas está haciendo en la pizarra1-2'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'b35f83961331213cfc0b76ce2af835aedeb07bd6942deefcfc2d290190ea1f1f'::TEXT, ARRAY[1151]::BIGINT[]),
    (298::BIGINT, 'El profe es buena nota, pero no califica nada hasta semana 19, es flexible con los trabajos y examenes, pero desordenado que se le ovida asignar cosas o se le olvida que las asigno. Da mas temas que los demas profes en este curso pero por suerte el ultimo examen no estuvo dificil.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bba324905e822a7e6f2b71916da63ce5bfc93316f0e95a19018782273f71a998'::TEXT, ARRAY[1151]::BIGINT[]),
    (298::BIGINT, 'El peor profe del tec. Semana 19 y usted no sabe la nota hasta el día de actas. Las evaluaciones valen muy poco y son muy largas y los examenes son muy volados y califica como le da la gana. No le pida consulta ni nada porque no la va a dar porque nunca contesta.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '6f734e8eed06f82e40044d8abba2f3843020822afbcf1d8a4b3b3e900b5b517d'::TEXT, ARRAY[1054]::BIGINT[]),
    (298::BIGINT, 'Jose Rafael Castro Mora es un profesor simplemente incompetente, el mae no sabe de lo que habla en clase y tan siquiera hace el esfuerzo de disimularlo. No revisa las evaluaciones sino hasta unas horas antes de la entrega de actas. Es una lástima que en la sede de San José esta basura da 5 cursos.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2023-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'f136afb517954aa144cec3a1b08b680ae86e177453fcf20f9b2edd2518d535dd'::TEXT, ARRAY[1151]::BIGINT[]),
    (298::BIGINT, 'Pésimo profesor. El profesor más malo de toda la escuela de computción. Explica mal, todas las calificaciones de los exámenes y tareas son al final del semestre, aunque los reglamentos indican que debe calificarlas 8 días después. Por favor no pierda su tiempo y dinero, no matricule con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'e203fd86cd9bf1bfecc15ea2611d27c449beb0508b5443d82c9bf8f68f215efa'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'No le hagan caso al mae de abajo. Este es, en mi opinión, legitimamente el peor profesor de todo el tec.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '5d2b73dda851280309e1e55130ef9473c284ed58efd7baaf890c068e0445baec'::TEXT, ARRAY[1054]::BIGINT[]),
    (298::BIGINT, 'Si quiere decepcionarse de estudiar computación, matricule con este profe. Muy desordenado, da todas las notas al final del semestre. Nunca llega a clase y explica supermal.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '94565e6f3e6b7fcf341d8eea28cd1f7e50121c28427b2f1a2a0c83505fcd99d7'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Da muchos cursos así que no pienses que te va a dar notas antes de la última semana, los exámenes hace uno y a veces deja el segundo como tarea, vale más la pena enfocarse en los proyectos. Muy difícil que te de 100 y sin retroalimentación pero no es muy difícil sacar la nota para pasar al menos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1c79dacd3f072704374a0303005929e5158c02bd3b9f8ce13fc61cf37727eb42'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Con Chepe es complicado, el mae cae bien y ayuda bastante, evalua super chill pero si es muy desordenado y usted realmente no va a aprender mucho. Si solo quiere pasar de una, si quiere aprender meta con Torres. Mi consejo es no se joda con las tareas cortas mucho trabajo para lo que valen.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4e329c6b2cb8582cc8d7ed6a4f270179776b0823e1066912e5425771cbff5710'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'El profesor utiliza Zoom y siempre se le olvida grabar las clases, y cuando lo hace las sube semanas después. Debes de ser capaz de hacer todas las tareas solo y los exámenes son difíciles, y solo da el tiempo de la clase para hacerlos. Se enoja si le pides que repita algo. No genera confianza.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '1ec535258675a388ae02e3edacc1f775b97c50cd557880cd476f455d3138da4b'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Terrible. Un profesor muy desordenado, los métodos de evaluación son fatales, los trabajos son irracionalmente largos y no valen los puntops que deberían valer. Además, es un vago. Dice que va a subir un examen un miércoles (por ejemplo) y lo termina subiendo DOMINGO. Deja todo para el final siempre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'dd0e8b6d72285781601e24827f447f85c0fef17a5e3fbcba06a77ca21a0a8be3'::TEXT, ARRAY[1154]::BIGINT[]),
    (298::BIGINT, 'Este profesor es el desorden en persona. Solo llega a leer una presentación que se robó de internet y la tradujo mal. Se hace un enredo explicando y al final uno termina aprendiendo mejor con google. Es tan desorganizado que le va a dejar un examen los domingos y califica todo al final del semestre.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '4f1e4914ac664a9d3ce73b22088d483348c07b120dabab62f3b79311b26db912'::TEXT, ARRAY[1154]::BIGINT[]),
    (298::BIGINT, 'El profe tiene mucho conocimiento, pero el problema es que no sabe transmitirlo de la forma correcta. Para entender los "dibujos" tienes que prestar mucha atención. Nunca contesta WhatsApp, da las notas hasta el último día del semestre. Tareas y trabajos complicados.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'caf4fbb240e851db4c2c9023782b84cbc03a41731bafb7d73436275c8cbc1d03'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Con solo entregar las cosas apesar que esten incompletas o malas ya vas ganar el curso. Las clases son demasiado confusas, muy desordenado y no se apega a la evaluacion y a la guia. Si usted quiere pasar meta con el, pero le advierto que usted no va a aprender absolutamente nada.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '99baa6b23a3c6101144abac1b5f031a4cca09502d7b3eabc41e19667c8a0ef7c'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Demasiado irresponsable, no se preocupa por sus estudiantes. Revisa las evaluaciones hasta final de semestre.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f394fc22f7d9e2921c3dee932ce0d43cf8bcad222708b8878b04e13983bd89a1'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Toca temas muy interesantes. La clase es más que todo atender y participar. Al principio dejaba lecturas un poco largas de un día para otro, pero luego era ver videos y dar su opinión. Se evalúa la participación aunque no siempre. Es un curso muy ameno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, 'ee6454391218ebb94f92746466cfb585134246feeca6c8b53ac9a75b27c8e2ad'::TEXT, ARRAY[1156]::BIGINT[]),
    (298::BIGINT, 'Con clases virtuales, se pone a hacer garabatos en awwapp para intentar explicar la materia pero se enreda mucho. Si no es con dibujos, es con presentaciones que tradujo con Google. Los exámenes son ambiguos en su mayoría y los proyectos o son tediosos o difíciles. Prepárese para ser ignorado por WA'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '30604e6eb38187ab8dfcfef0410038a3c4b02713e06bd93fade4de27e2898bbf'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Con él hay que investigar, porque muchas veces no va a explicar el lenguaje o habrán algunos temas que no van a quedar claros.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '0a295d5003ddcdcd961e29513cf37c277d57a8eef772decd83431a54893d2651'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'La verdad me parece un mal profe, no planifica la materia ni el curso, contesta muy tarde los mensajes, deja tareas súper pesadas que no dejan aprendizaje y que al final no valen casi nada, revisa todas las evaluaciones faltando una semana para que acabe el curso. Si se aman no matriculen con él :c'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-01-05T00:00:00+00:00'::TIMESTAMPTZ, '794b6ffe5536bcb04c9f7cb388a752ba295ae58316b3f2790d981a624b2a7dab'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Un completo desastre'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '0814075e019f4da849afd5f07b2d07935bc0be1837220e91aae7f4c58dfb45f5'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Es un profe que sabe demasiado sobre los temas pero talvés a la hora de explicar pueda ser un poco difícil entenderle en ciertos puntos de la materia. Como persona es muy pura vida, amigable y entiende a los estudiantes cuando necesitamos tiempo o ayuda. Eso sí, puede que sea un poco desordenado'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '4fd1b5a4c9944dc211a3390c5ddee121fb1ea694cf7a9d606b3b49d50f8e9119'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'En clases virtuales las graba y las deja disponibles para todos, el curso tiene algunos temas complicados y a veces el profe se enreda con su desorden de apuntes.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '400985f1df3559b20f0f753d092d1653dcbc20019fb7c6123c95bacbe8583390'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Primera vez que da este curso y lo dió de la peor manera posible, no matricule con este profesor, decide evaluar 70% de la nota en dos semanas sin ningún tipo de especificación. Pide excesivas exposiciones/quices/ensayos que no sirven para nada y al final no valen tampoco.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa']::TEXT[], '2020-07-21T00:00:00+00:00'::TIMESTAMPTZ, '12d826f1997ea203b88fafc171f131a4e4493abb62903dcbc6433ab80d2e81fd'::TEXT, ARRAY[1156]::BIGINT[]),
    (298::BIGINT, 'Huya de este profe!! Si no tiene otra opción, mejor espere un semestre para matricular con alguien más. Es pésimo!!!!! No explica nada, no se sabe como califica, un desastre en la pizarra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Pocos exámenes']::TEXT[], '2020-03-06T00:00:00+00:00'::TIMESTAMPTZ, '8be0650c4fd4e9c59cb376a4d0e0022d1ceef10cdcacbb6a6259b3cf4f968aae'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Muy desordenado, califica todo hasta el final, pero es muy pura vida. Cae muy bien y si se le pide tiempo para las tareas lo da hasta antes de actas. Muy estricto con las progras, por lo más mínimo que vea mal, baja puntos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'e6601dcf824a3e2b28fcf2bcd921e2bfbdf67fd63dd364c313f0deea777ac143'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'El peor profesor de la vida, desorganizado, no da notas, no le interesa si usted aprende o no, se le pide que explique y no explica nada, lo peor que le pueda pasar en su vida, huya.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '7147da1dff9fb16eb1dc7b75ebcb54182aca04c6d539baabd7526650cc9d5d16'::TEXT, ARRAY[1154]::BIGINT[]),
    (298::BIGINT, 'Uffff que profe tan malo! De verdad que hace que uno se cuestione si está aprendiendo algo. Explica pésimo, entrega todas las notas al final del semestre. Califica subjetivamente. Si no le queda otra cosa por hacer, matricule con él. Sino, cualquier otro profe es mejor.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2019-08-22T00:00:00+00:00'::TIMESTAMPTZ, '23a2621bb276f943967f996848516f7e5f548339aa52c5c550ef57a317d57be4'::TEXT, ARRAY[1162]::BIGINT[]),
    (298::BIGINT, 'Terrible, no lo puedo recomendar. Es imposible no dormirse en las clases, es un desorden y uno no sabe si va a pasar. La rúbrica de calificación que nos dio al principio ni la usó y no hubo revisiones para las progras. No aprendí nada del curso, fatal.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bbe53c7a55e27d3bfc794aac76cc403e89a3816bdc62963146c5c32ea4d4be5a'::TEXT, ARRAY[1154]::BIGINT[]),
    (298::BIGINT, 'Es un total desorden de profesor, no entrega notas si no hasta el día de actas. Por parte de la materia, es un jefazo que resuelve cualquier problema pero a un ritmo exageradamente rápido por lo que uno se pierde. Si es repitente, se puede mandar, si no llévelo en otro lado.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c7aca3c3e6cfdc6b533a10d5a5f968525044934ba67d9e5a8577eb41cd72afa4'::TEXT, ARRAY[1151]::BIGINT[]),
    (298::BIGINT, 'Profesor inteligente pero muy desordenado. Posible pasar sin haber aprendido nada. Revisa a final de semestre sin dar retroalimentacion'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Pocos exámenes']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fd74f79628533142a0956cd936a8aa891173f5f0dea246b29a810a238049a0b9'::TEXT, ARRAY[1162]::BIGINT[]),
    (298::BIGINT, 'Se aprende algo, poco, pero algo es algo. Tiene mucho conocimiento y ayuda mucho, para este curso no es tan malo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-01-26T00:00:00+00:00'::TIMESTAMPTZ, '7067fcb66478c438f56f358d62707c45b798e4aeb96dd86be37dfc2c9b1f7c5b'::TEXT, ARRAY[1154]::BIGINT[]),
    (298::BIGINT, 'Es demasiado tuanis este profe, tiende a explicar sumamente rápido por eso es que uno se pierde, hay que ser muy autodidacta para poder llevar el ritmo del curso pero lo compensa con no ser extremadamente rudo a la hora de calificar.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Inspirador']::TEXT[], '2018-12-08T00:00:00+00:00'::TIMESTAMPTZ, '1f44335045a74e82e98d7399de87fba528aa5165db9faa25b79ec4ca55ff7082'::TEXT, ARRAY[1054]::BIGINT[]),
    (298::BIGINT, 'No revisa ni entrega nada de los proyectos ni de las tareas. Al final todo el mundo pasa el curso, pero sin haber aprendido nada. No sabe explicar, eso es si llega a clases.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2018-09-28T00:00:00+00:00'::TIMESTAMPTZ, '8634cdb0437a2760a57fa74fc1d52763df73ddb86367635dbeaa9eae910ac1d6'::TEXT, ARRAY[1020]::BIGINT[]),
    (298::BIGINT, 'Si se le pide quiz de asistencia el mae los da, el mae revisa las tares como en semana 19 o en entrega de actas y pone 100 practicamente regalo el curso'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'c980380000d0fa7c8f5951eece1cf393e2b3b4980550393c8e3a58a83942e775'::TEXT, ARRAY[1054]::BIGINT[]),
    (298::BIGINT, 'Cuesta mucho entenderle por lo desordenado y además por que habla muy bajito. Es un desordenado con las calificaciones de proyectos, quizes, etc. Puede que sea una de las personas más inteligentes de la Escuela de Computación, pero como profesor es de los peores. Al final todos pasan con 90. WTF.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6ac6db0ffbe44a0fcefb9e691f055d3fbbec2ac197f5eaff9587dcc612b0a01a'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Jose es muy buena gente, el hace lo posible para que el estudiante aprenda pero se debe ser muy autodidacta en el curso, las presentaciones de proyecto suelen ser elaboradas e incluso complejas (en algunos casos), si es un poco desordenado con las evaluaciones pero califica suave :)'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ca9d0e926644def8c9669fef915e46a829e42d84b0ed5e1897876b416ec0ee0e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (298::BIGINT, 'El mae es buena gente pero no lo recomendaría como profesor de los primeros cursos de la carrera o para primer ingreso. No explica mucho que digamos así que hay que ser muy autodidacta para pasar. eso si el mae califica super suave y da opurtunidades para reponer examenes o tareas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '30496ea18800cc9e03d2aa3852f7fcd6e8c1aea42b70da08db7fab9439b5fcec'::TEXT, ARRAY[1021]::BIGINT[]),
    (298::BIGINT, 'Es desordenado por naturaleza pero como se agarra del libro y las presentaciones del libro todas las clases, le ayuda a mantener un orden, deja muchas tareas del libro pero todas se pueden hacer, califica suave, proyectos y laboratorios también son del libro y la materia es muy entendible.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '8b12ff2993dfb8e413277fbea9af3e52fa2a836bc33137a8c01b078cdd3dc384'::TEXT, ARRAY[1154]::BIGINT[]),
    (298::BIGINT, 'Chepe es todo un caso. Se ve que conoce la materia, y es buena gente, pero las clases son demasiado desordenadas. A veces falta y no avisa de antemano. Califica practicamente al azar, nunca se sabe.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b0238e3db08ef96337b90b84ca6135b92a666ada009c8d78a64b282e1b49cb13'::TEXT, ARRAY[1162]::BIGINT[]),
    (298::BIGINT, 'De los cursos que he llevado con él es en este donde más le he entendido. Hay que preguntarle para entender, y sabe un montón. Es suave en evaluaciones. Los proyectos son sencillos (siempre y cuando se evacúen las dudas con él). Hay que tener autoaprendizaje.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7724a8d5e7f78144ebc1ca284211217f438bd7ae2245579a0b745747e753a8a1'::TEXT, ARRAY[1151]::BIGINT[]),
    (298::BIGINT, 'El profesor es buena gente pero simplemente no sabe explicar. Las clases se vuelven complicadas de entender y si le preguntas te da respuestas ambiguas. Si es posible, matricular este curso (que utiliza mucha materia de las mates) con otro que sí profesor pueda explicar.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-19T00:00:00+00:00'::TIMESTAMPTZ, '27091ca144c4025cd71c98ecbd43832ed7ea409717863d850999d5217d3e9e51'::TEXT, ARRAY[1151]::BIGINT[]),
    (298::BIGINT, 'Qué profe más malo. De verdad que hace que uno se pregunta cómo contratan a alguien así para dar clases. No sabe explicar nada, siempre llega tarde, muchas veces trasnochado. Se ve que no le interesa explicar nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '676dbfdbe3c8613e9701267c36ed7869a9a3fef52722155b42d62fc3ea995784'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Es uno de esos profesores que se nota que tienen una amplia gama de conocimientos pero que no saben transmitirlo. Entonces si usted desea levantarse e ir a la universidad a pasar dos horas sin entender absolutamente nada, solamente cuestionándose porque esta en la Universidad, hágalo.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'd56c632540ae554e3909800e7cd742fb454437221ec71659f4d0891a15f4380f'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'No debería ser profesor. Quédese hasta el final, puede que cuando esté inventando notas (algo que él siempre hace el día de entrega de actas), lo pase.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-03-23T00:00:00+00:00'::TIMESTAMPTZ, '7b4e862f4a6f55349b0aaad67141e47f01f083bbd2e3a6599f1e1efdea5b0f51'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Cuesta entender, pero algo se aprende, la asistencia no es obligatoria pero suele hacer quiz de asistencia (hasta 4 en un curso) y da puntos por pasar a pizarra. Como ultimo concejo puede creer que esta quedado pero con este profe uno nunca sabe, quedese hasta el final,'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2016-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'ae70cb39927e1d8f956787364a088182c443d3dbd994ec9dfb5a643866d306aa'::TEXT, ARRAY[1035, 1045]::BIGINT[]),
    (298::BIGINT, 'Profe que sabe de todo , confusa sus clases , uno aprende haciendo las progras pero son difíciles'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2016-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'e0c2fbb6c003f857b1801da71c72622bdf0fdcbcdaf5e0358810fe72db801d90'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'No explica muy bien. En algunas clases se le entiende y en otras no. Los proyectos y examenes no son muy largos, pero si un poco complicados. Lenguajes vistos: Haskell y Prolog. Lo malo es que uno no sabe nada de las notas hasta que se aproxima (o es el día de) la entrega de actas.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '239c6414504371ba1875220c6cdc9c6c9afce378f8104e28c93d4acae193b4f2'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Muy mal "profesor", todo se le olvida y explica pésimo. No sé como sigue dando clases. Falta y no avisa con antelación. Si quiere aprender no se lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'c12b7158dcae4532f8537b0bbca39dd4c117fb2503998f46a9284d638a7be022'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Profesor que sabe demasiado... algo confusas sus clases, pero algo se aprende????'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'a51c975f39fbeca46c91e7a6ecee95647c8158246c407901c6314b8edeaa10e0'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'El curso con él es confuso. En algunas clases es factible entenderle, pero esas son el 10% de todas las lecciones, en las demás es muy probable que no se entienda, esto añadiendo las tareas que deja al respecto. Uno no sabe cómo va en el curso, ahí se verá en las actas.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '6a3c53800600dd09dca26741f47811cde87534c4fc94b2fbc26e04ff4e548635'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Explica confusamente la materia de la clase'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '8e453cb12150cf9ec32b19208d0ef001bd64cfe0c4ecb3ad66b5332b124a5a73'::TEXT, ARRAY[1162]::BIGINT[]),
    (298::BIGINT, 'El profe sabe mucho de computacion pero no sabe expresa ese conocimiento. Es bastante desordenado y vago'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'ed1c71589a0c4ca122c9461dc0ed433b380cb00bda71b1ee6da2b90a977e3b33'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Cuando explica lo teórico se le entiende, en lo practico, se le tuesta a uno el cerebro, de feria no le gusta volverlo a explicar.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, '4d6851c2d4f20c7e87afa9784e62bc9ae7c1121cc4a0971940586396740a9289'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Sabe mucho sobre computación pero le cuesta expresarlo. Hay que agarrarle el toque para entenderle por lo que al principio es difícil. Desordenado con evaluaciones y notas finales.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '14859c893213189a60b183ff1e98c01ee6a97a762d612b60684acc0b0c523d55'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Pésimo profesor: notas random, falta cuando quiere, vago y no sabrá nada de sus notas hasta entrega de actas. Evítelo todo lo posible.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '51148d99198117d623cf3f506233788d7e4d41541da71973566de6faa9fb31e4'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Si tienen una mente matemática, analítica, son autodidactas y les gusta realizar evaluaciones justo antes de la entrega de actas, lleven con él. Sino, evitenlo en lo mayor posible'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'dc2ac49c594d76b87741174806b2f8e624a6b720ff86aded5f9d757975b8a3c3'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Es buen profesor y si le gusta la teoría de computación es muy buena opción hay que leer libros para llevarle el hilo pero la verdad lo considero buen profesor es un poco desordenado con las evaluaciones pero al final las revisa y la verdad no molesta mucho y se aprende'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-15T00:00:00+00:00'::TIMESTAMPTZ, '7cc585f53b972f1218400235867da99e3bc999621f1620ccbd5103a351aa604c'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Si quiere matricular un curso de algoritmos, él no es la mejor opción. Sin embargo, si quiere comprender aspectos avanzados de computación, tenés a la mayor referencia acá en el TEC.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2016-02-03T00:00:00+00:00'::TIMESTAMPTZ, '13dd10194e91b03e3289be8634ce70b6cf72450b32bb4dc8363d4875625ab6e5'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Es entendible hasta cierto punto, pero las clases no se hilan y pueden llegar a ser aburridas. Da por hecho que el estudiante sabe más y deja de explicar algunas cosas por eso. No entrega notas en lo absoluto, entonces uno no sabe cómo va sino hasta final de semestre.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'd08526528ed71ffd7f13ecf6bfadf98f264882fecec42ab9b3a2c09b8e8fd17a'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'El es buena gente, pero no sabe explicar al nivel de uno, parece que piensa que uno ya es graduado y tiene los conocimientos, no revisa nada, y es relajado con el tiempo lo que es bueno porque da mas tiempo para trabajos si se le pide, pero malo porque se acumula al final si no le recuerdan.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'a014b5a66b13fbab5f2ff9f534f10c45ab764671f6a5e89edc6010fc0028bc93'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'La materia persé es super abstracta y él explica mucho pero le da vueltas a todo. No logra rebajarse al nivel del estudiante, entonces no se entiende lo que hay que hacer y como. Aunque no revisa las tareas y regala muchos puntos, fue un semestre aburrido y confuso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'd96d3ed3da6fe43f57b970cd7ac642febf586fa4048559eeb2edba2ac9d2441c'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'No se le entiende nada, pero alguillo aprende uno'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '169ffbdea1e926758fe9e141e4313596ea817b6c6947dac8d9af313dd0d247a0'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Simplemente es el peor profesor de Compu'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '917c0e2ca8fcd903baf2c0d8c3fc35f3bd38429e8add77f036fb6c9590858224'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Muy irresponsable con los trabajos'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-12T00:00:00+00:00'::TIMESTAMPTZ, '39490e307acd9ec77208cf38950ba4493dac542a42ef3b415503b53738c2a3bb'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Explico todos los temas, clases muy interesantes y útiles, casi siempre se vuela y se pone a tirar algoritmos en la pizarra a lo bestia, no transmite conocimientos y las notas son random siempre, pues al final de semestre siempre se le daña el disco duro de la compu jaja'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'd775b0c288a131a67718359264d8223183a6f1d66b61575b0ae6599bd64e3dfe'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Muy desordenado, no devuelve nada revisado, no prepara clases, lleva videos para ver en clase, deja proyectos interesantes, es comprensivo con el tiempo, falta a clases sin avisar, sabe mucho pero no lo transmite.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '295efd6e746cf6ba96e404ffcae4b235a39cc68422986be7e2e842a6c3f315bc'::TEXT, ARRAY[33]::BIGINT[]),
    (298::BIGINT, 'Sabe demasiado, pero no tiene pedagogía. Si logra entender 1 o 2 temas en todo el semestre es demasiado. Nunca se sabe nada de las notas porque no entrega nada, no revisa las varas... se dará cuenta si pasa hasta entrega de actas... a la mano del pastafarismo'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '8a449599a0cd0ca61e673371c0f622d6d4fc754270134e555d5072dc1e32a14b'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Es bueno como persona pero como profesor se queda corto. Se nota que sabe mucho pero no logra transmitirlo. Las clases son confusas si es que hay clases, desaparece de vez en cuando. Uno no tiene idea de como va ya que no revisa ni entrega nada, al final si tiene suerte pasa con un 70 mágicamente.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'eaa593823828bd1df69d64217f72cd342911926080895b015b752410cd5a13bc'::TEXT, ARRAY[1045]::BIGINT[]),
    (298::BIGINT, 'Uno no aprende mucho, solo es de esperar al final del curso la nota, porque uno no sabe como va'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '09194b3773970e50d7fe6408a02b280a3cf56e3e4ea484830056364ed081a923'::TEXT, ARRAY[1035, 1045]::BIGINT[]),
    (298::BIGINT, 'Análisis de algoritmos fue la materia en la que todo el grupo aprendió por su propia cuenta.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b06be268e9b136115d34d1b53eb50ffe53a9b103d6a2074d00e7fa1d8218b30c'::TEXT, ARRAY[1035]::BIGINT[]),
    (298::BIGINT, 'Si matricula con él y entrega la mayoría de trabajos pasa con alta nota pero al final del curso va irse como vino en cuanto conocimiento'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '3ae785c1e6a025bd68e2aff2d9ed311dbbb7d26b71f8c7c93046d89455e9ea76'::TEXT, ARRAY[1029]::BIGINT[]),
    (298::BIGINT, 'El profe es un crack! sabe demasiado pero cuesta demasiado entenderle puesto que es un poco desorganizado!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ba6932e4add14bf036584a25f26bbc6de154dd0bbb32dc6f5bcd9a2a0656ee38'::TEXT, ARRAY[1151, 1045, 1035]::BIGINT[]),
    (298::BIGINT, 'Materia demasiado volada, es muy inteligente, pero solo el entiende lo que habla, demasiado desorganizado.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a80642a51f99f949a1163cf03df4939835e3d7a3027cd0c8a2f30f98301c131a'::TEXT, ARRAY[1045]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
